import logging
from taf.hw.rf_attenuator.devices.topyoung.topyoung import TopYoung
from taf.hw.rf_attenuator.exceptions import AttenuationSetError, AttenuatorInitiationFailed


class TopYoungTAS8T8BNECDNSWT030451(TopYoung):
    _SET_CMD = 'set {},{}'
    _SET_RES_OK = 'set ok'
    _SET_RES_FAIL = 'set error'
    _READ_CMD = 'read {}'
    _READ_RES_OK = r'read id {} value (\d+)'
    _READ_RES_FAIL = 'read error'
    _CMD_ERR = 'command error'
    _DISPLAY_MODE_CMD = 'status'
    _SET_REMOTE_MODE_CMD = 'remote'
    _LOCAL_MODE = 'mode local'
    _REMOTE_MODE = 'mode remote'
    _VENDOR_INFO = 'www.topyoung.com.cn'
    _UNTIL_FLAG = 'TopYoung>>'

    def __init__(self, **kwargs):
        super(TopYoungTAS8T8BNECDNSWT030451, self).__init__(**kwargs)

    def _set_remote_mode(self):
        mode_result = self._write_and_read(self._DISPLAY_MODE_CMD)
        if self._LOCAL_MODE in mode_result:
            logging.info('Need to set mode from local to remote.')
            self._write_and_read(self._SET_REMOTE_MODE_CMD)
        elif self._REMOTE_MODE in mode_result:
            logging.info('Current mode is remote already.')
        else:
            raise AttenuationSetError('Mode result: {}'.format(mode_result))

    def _get_vendor_info(self):
        return self._write_and_read(cmd='\r')

    def _init_device(self):
        vendor_result = self._get_vendor_info()
        if self._VENDOR_INFO in vendor_result:
            self._set_remote_mode()
            logging.info('Initiated attenuator successfully.')
        else:
            raise AttenuatorInitiationFailed('Attenuator vendor info: {}'.format(vendor_result))

    def connect(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-channel of that device
        """
        super(TopYoungTAS8T8BNECDNSWT030451, self).connect(**kwargs)
        self._init_device()

    def _write_and_read(self, cmd, timeout=5):
        cmd_result = self._telnet.read_command_output(command=cmd, read_method='until', read_flag=self._UNTIL_FLAG)
        logging.debug('The response of command: \n{}'.format(cmd_result))
        return cmd_result
